.tool-ui {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* 横並びコンテナ */
.side-by-side {
  display: flex;
  gap: 1em; /* 左右の間隔 */
  max-width: 1600px; /* 800px × 2 + gap */
  width: 100%;
  align-items: stretch; /* 高さを揃える */
}

/* ★修正箇所★: side-by-sideの子要素にflex: 1を適用し、均等に幅を分割 */
.side-by-side &gt; textarea,
.side-by-side &gt; .output-container {
    flex: 1; /* 均等な幅を確保 */
    /* width: 100%; の競合を防ぐため、この設定が優先されます */
}


textarea {
  /* width: 100%; はflex: 1と競合するため削除 */
  min-width: 350px; /* 最小幅 */
  min-height: 350px; /* 高さを揃える */
  padding: 1em;
  font-family: monospace;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
  resize: both; /* 縦横両方リサイズ可能 */
  box-sizing: border-box;
}

.output-container {
  /* width: 100%; はflex: 1と競合するため削除 */
  min-width: 350px;
  min-height: 350px; /* textareaと高さを揃える */
  margin: 0; /* margin-topを削除 */
  position: relative;
  background: #fff;
  border: 1px solid #ccc;
  border-radius: 4px; /* 見栄えを良くするため追加 */
  padding: 1em;
  white-space: pre-wrap;
  font-family: monospace;
  box-sizing: border-box;
  overflow-x: auto; /* 念のため、出力が長すぎた場合に横スクロールを許可 */
}

/* preタグのスタイル: 出力内容がコンテナの幅からはみ出ないように設定 */
.output-container pre {
    margin: 0;
    white-space: pre-wrap;
    word-break: break-all;
}



.button-1 {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100px;
    margin:0 auto;
    padding: .9em 2em;
    border: 1px solid #5F5E5E;
